import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import Button from 'react-bootstrap/Button'
import Spinner from 'react-bootstrap/Spinner'

class SearchForm extends Component {
    
    /*initialState = {
        url: '',
        enableSearchSubmitButton: false
    }

    state = this.initialState*/
  
    handleChange = event => {
        const { name, value } = event.target
  
        this.setState({
          [name]: value,
            searchUrl: value
        }, () => {
            let enableSearchSubmitButton = searchUrl.length > 0;
            this.setState({enableSearchSubmitButton: enableSearchSubmitButton});
        })
        
    }
    
    submitForm = () => {
        this.props.handleSearchSubmit(this.state)
        //this.setState(this.initialState)
    }
    
    render() {
        
        const state = this.props.state;
        console.log(state);
        
        const searchUrl = state.searchUrl;

        const showSearchSubmitButton = state.showSearchSubmitButton ? {display: 'block'} : {display: 'none'};
        const showSearchSubmitLoadingButton = state.showSearchSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
        
        const enableSearchSubmitButton = searchUrl.length > 0;
        
        return (
          <Form onSubmit={this.onFormSubmit} >
            <Form.Group>
                <Form.Label>Soundcloud Song URL</Form.Label>
                <Form.Control
                    type="text"
                    name="searchUrl"
                    id="searchUrl"
                    onChange={this.handleChange} />
            </Form.Group>
    
            <Button type="submit" value="Submit" disabled={!enableSearchSubmitButton} onClick={e => {e.preventDefault(); this.submitForm()}} style={showSearchSubmitButton}>Submit</Button>
            
              <Button variant="primary" disabled style={showSearchSubmitLoadingButton}>
                <Spinner
                  as="span"
                  animation="grow"
                  size="sm"
                  role="status"
                  aria-hidden="true"
                />
                Loading...
              </Button>
          </Form>
          
        );
    }

}

export default SearchForm;
